:host {
  background: var(--aevko-background, #ffffff);
  border: 1px solid var(--aevko-border, #e4e4e7);
  border-radius: var(--aevko-radius, 0);
  color: var(--aevko-foreground, #20201e);
  display: grid;
  font-family: var(--aevko-font-sans, sans-serif);
  gap: 1.5rem;
  padding: 1.5rem;
}

:host {
  align-items: start;
  display: grid;
  gap: 0.5rem;
  grid-template-columns: minmax(0, 1fr) auto;
}

:host {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}

:host {
  align-items: center;
  display: flex;
  gap: 0.5rem;
  grid-column: 2;
  grid-row: 1 / span 2;
}
